<?php require 'includes/config.php';header('Content-Type: application/json');if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);exit('{}');}if(!user()){http_response_code(401);exit('{"error":"Log in to save scores"}');}verify_csrf();$game=$_POST['game']??'';$score=filter_var($_POST['score']??null,FILTER_VALIDATE_INT);if(!in_array($game,['tic','puzzle','quiz'],true)||$score===false||$score<0||$score>1000){http_response_code(422);exit('{"error":"Invalid score"}');}db()->prepare('INSERT INTO scores(user_id,game,score) VALUES(?,?,?)')->execute([user()['id'],$game,$score]);echo '{"ok":true}';
